<script setup>
import {computed,shallowRef,ref} from 'vue';
import {newPinball,launchPinball,stepPinball,pinballBumpers,pinballFlippers,validatePinball} from '../../room/pinballGame.js';
import {useLocalDraft} from '../../composables/useLocalDraft.js';
import {useArcadeLoop} from '../../composables/useArcadeLoop.js';
import {useInteractionAudio} from '../../composables/useInteractionAudio.js';
import {recordActivity} from '../../room/activityLog.js';
const validate=v=>{if(!v||v.version!==1)throw new Error();return {version:1,round:validatePinball(v.round),best:Math.max(0,Math.floor(v.best)||0)};};
const {state,saved,persist}=useLocalDraft('hitori-room:pinball:v1',{version:1,round:newPinball(),best:0},validate),round=shallowRef(validatePinball(state.value.round)),audio=useInteractionAudio('pinball'),sound=ref(false),power=ref(0),charging=ref(false);
const controls={left:false,right:false,nudge:false},flippers=computed(()=>pinballFlippers(round.value));
let chargeAt=0;
function save(){state.value.round={...round.value,hits:{...round.value.hits},events:[]};state.value.best=Math.max(state.value.best,round.value.score);persist();}
function pause(){controls.left=false;controls.right=false;controls.nudge=false;charging.value=false;power.value=0;if(round.value.phase==='playing')round.value={...round.value,phase:'paused'};audio.stop();save();}
const loop=useArcadeLoop(dt=>{if(charging.value)power.value=Math.min(1,(performance.now()-chargeAt)/900);const previous=round.value;round.value=stepPinball(previous,controls,dt);controls.nudge=false;if(sound.value&&round.value.events.length)audio.play('guitar',pinballBumpers.find(b=>b.id===round.value.events[0])?.frequency||392);if(round.value.phase!==previous.phase){save();if(round.value.phase==='over'){recordActivity('pinball',`一局 ${round.value.score} 分`,`${Date.now()}:${round.value.score}`);loop.stop();}}},pause,key);
function hold(name,event,down){event.preventDefault();if(down)event.currentTarget.setPointerCapture(event.pointerId);if(name==='launch'){if(down&&['ready','waiting'].includes(round.value.phase)){charging.value=true;chargeAt=performance.now();power.value=0;loop.start();}else if(!down&&charging.value){round.value=launchPinball(round.value,power.value);charging.value=false;power.value=0;loop.start();}}else controls[name]=down;}
function cancel(name){if(name==='launch'){charging.value=false;power.value=0;}else controls[name]=false;}
function key(e){const name={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',' ':'launch',n:'nudge',N:'nudge'}[e.key];if(!name)return;e.preventDefault();if(e.repeat)return;hold(name,{preventDefault(){},currentTarget:{setPointerCapture(){}},pointerId:0},e.type==='keydown');}
function resume(){if(round.value.phase==='paused')round.value={...round.value,phase:'playing'};loop.start();}
function reset(){loop.stop();round.value=newPinball();save();}
async function toggle(){if(sound.value&&!await audio.setEnabled(true))sound.value=false;if(!sound.value)audio.stop();}
</script>
<template><section class="room-panel" aria-labelledby="pinball-title"><div class="pg-heading"><div><p class="pg-kicker">BOUNCE INTO THE BEAT / 音符を、もう一度</p><h2 id="pinball-title">再接住一次，就能多响一拍。</h2><p class="room-intro">按住发射蓄力，松开发球。左右挡板接住小球，碰撞乐器与音符累积分数。</p></div><span class="pg-number">22</span></div><div class="pg-split"><div class="pg-board pinball-board" tabindex="0" aria-label="弹珠台，左右键控制挡板，空格发球，N 轻推"><svg viewBox="0 0 600 880" role="img" aria-label="音乐弹珠台"><defs><radialGradient id="pinball-glow"><stop stop-color="#6a536e"/><stop offset="1" stop-color="#292536"/></radialGradient></defs><rect width="600" height="880" rx="45" fill="url(#pinball-glow)"/><path d="M40 650V90H560V650L435 760M40 650L165 760" fill="none" stroke="#bca4c3" stroke-width="12" stroke-linejoin="round"/><text x="300" y="62" text-anchor="middle" fill="#e8d8de" font-size="19" letter-spacing="5">ONE MORE BEAT</text><text v-for="i in 6" :key="i" :x="100+(i-1)*84" y="153" fill="#e9cb84" text-anchor="middle" font-size="28">♪</text><g v-for="b in pinballBumpers" :key="b.id"><circle :cx="b.x" :cy="b.y" :r="b.r+9" :stroke="b.color" fill="none" stroke-width="2"/><circle :cx="b.x" :cy="b.y" :r="b.r" :fill="b.color"/><text :x="b.x" :y="b.y+7" text-anchor="middle" fill="#49394f" font-size="22">{{{guitar:'♬',bass:'≋',drum:'✦'}[b.id]}}</text></g><path d="M90 480Q300 600 510 480" fill="none" stroke="#967d9a" stroke-width="3" stroke-dasharray="10 12"/><text x="300" y="615" fill="#c5a8bf" text-anchor="middle" font-size="24">{{round.combo>1?`${round.combo} COMBO`:'KEEP THE BEAT'}}</text><line v-for="f in flippers" :key="f.side" :x1="f.x" :y1="f.y" :x2="f.ex" :y2="f.ey" :data-flipper="f.side" stroke="#e4b5cc" stroke-width="22" stroke-linecap="round"/><circle id="pinball-ball" :cx="round.x" :cy="round.y" r="11" fill="#fff1cf" :data-phase="round.phase"/><text v-if="round.phase==='paused'||round.phase==='over'" x="300" y="680" text-anchor="middle" fill="#fff1cf" font-size="28">{{round.phase==='over'?'本场结束':'已暂停'}}</text><text x="300" y="840" text-anchor="middle" fill="#c5a8bf" font-size="17">{{['ready','waiting'].includes(round.phase)?'拉下发射杆，松开就出发':'留住每一个弹起来的音符'}}</text></svg></div><div><dl class="room-stats"><div><dt>得分</dt><dd id="pinball-score">{{round.score}}</dd></div><div><dt>小球</dt><dd>{{round.lives}} / 3</dd></div><div><dt>本机最高</dt><dd>{{state.best}}</dd></div></dl><div class="pg-touch-controls"><button v-for="(label,name) in {left:'左挡板',right:'右挡板',launch:'蓄力发射',nudge:'轻推'}" :key="name" :data-control="name" :disabled="name==='launch'&&!['ready','waiting'].includes(round.phase)" @pointerdown="hold(name,$event,true)" @pointerup="hold(name,$event,false)" @pointercancel="cancel(name)" @lostpointercapture="cancel(name)">{{label}}</button></div><progress :value="power" max="1" aria-label="发射蓄力"></progress><div class="pg-toolbar"><button v-if="round.phase==='paused'" id="pinball-resume" class="primary" @click="resume">继续这一球</button><button :disabled="round.phase!=='playing'" @click="loop.stop">暂停</button><button @click="reset">重新开一局</button></div><div class="pg-checks"><label><input v-model="sound" type="checkbox" @change="toggle"> 碰撞音效</label></div><p class="pg-legend">左右方向键 / A D：挡板<br>空格：按住蓄力，松开发球<br>N：轻推（每三秒一次）<br>连续碰撞两秒内续上连击，每三连击增加倍率，最高 ×5。</p><p class="pg-small">点击台面后可用键盘。切换窗口会暂停。最高分和暂停的小球{{saved?'保存在本机':'暂时无法保存'}}。</p></div></div></section></template>
<style scoped>.pinball-board{max-width:480px;margin:auto;touch-action:none}.pg-touch-controls button{font-size:13px;flex:1 0 40%}.pg-split{grid-template-columns:minmax(0,1.2fr) minmax(200px,.8fr)}progress{width:100%;accent-color:#b68ca6}@media(max-width:760px){.pg-split{grid-template-columns:1fr}.pinball-board{width:min(100%,380px)}}</style>
